def ajustar_plazos(apps, schema_editor):
    """
    En copropiedad el plazo para apelar pasa a contarse en dias habiles, entre
    5 y 10: el antiguo default (5 corridos) queda en 10 habiles y cualquier
    otro valor se acerca al rango. El plazo del Comite no puede pasar de 20.
    Otros verticales (obras, etc.) conservan sus plazos.
    """
    Condominio = apps.get_model('condominios', 'Condominio')
    for c in Condominio.objects.filter(models.Q(vertical__isnull=True) | models.Q(vertical__slug='copropiedad')):
        descargo = 10 if c.plazo_descargo_dias == 5 else min(max(c.plazo_descargo_dias, 5), 10)
        resolucion = min(max(c.plazo_resolucion_dias, 1), 20)
        if (descargo, resolucion) != (c.plazo_descargo_dias, c.plazo_resolucion_dias):
            Condominio.objects.filter(pk=c.pk).update(
                plazo_descargo_dias=descargo, plazo_resolucion_dias=resolucion,
            )


